// Task-local EXP-097 proof. Reference headers are git-archived from 1302d639,
// unmodified, Apache-2.0, and wrapped in a namespace to coexist with master.
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cstddef>
#include <cstdint>
#include <type_traits>
#include <utility>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>
#include "ops/linear/kernels/q4/q4_a16_sliced_k_mma.cuh"
#include "ops/linear/kernels/q5/q5_a16_sliced_k_mma.cuh"
namespace shipped_reference {
#include "ops/linear/q4/q4_small_t_mma.cuh"
#include "ops/linear/q5/q5_small_t_mma.cuh"
}
namespace current = ninfer::ops::detail;
namespace shipped = shipped_reference::ninfer::ops::detail;
static void check(cudaError_t error) {
    if (error != cudaSuccess) {
        std::fprintf(stderr, "%s\n", cudaGetErrorString(error));
        std::exit(2);
    }
}
template<class T> struct Buffer {
    T* data{};
    explicit Buffer(std::size_t count) { check(cudaMalloc(&data, count * sizeof(T))); }
    ~Buffer() { cudaFree(data); }
    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;
};
struct Store {
    __nv_bfloat16* data;
    int rows;
    __device__ void store(int row, int token, float value) const {
        data[std::int64_t(token) * rows + row] = __float2bfloat16_rn(value);
    }
};
struct Identity { __device__ float apply(int, int, float value) const { return value; } };
template<int Rows> struct Geometry {
    static constexpr int kInputRows = 5120;
    static constexpr int kOutputRows = Rows;
    static constexpr int kGroupsPerRow = kInputRows / 64;
};
std::size_t total_values = 0, total_mismatches = 0;
bool first = true;
template<bool Q5, int Rows, int Tokens> void compare(unsigned seed) {
    constexpr int K = 5120;
    std::mt19937 random(seed);
    std::uniform_real_distribution<float> value(-1.0f, 1.0f);
    std::uniform_real_distribution<float> scale(0.001f, 0.125f);
    std::vector<std::uint8_t> codes(std::size_t(Rows) * K / 2), high(std::size_t(Rows) * K / 8);
    std::vector<__half> scales(std::size_t(Rows) * K / 64);
    std::vector<__nv_bfloat16> input(K * Tokens);
    for (auto& x : codes) x = static_cast<std::uint8_t>(random());
    for (auto& x : high) x = static_cast<std::uint8_t>(random());
    for (auto& x : scales) x = __float2half(scale(random));
    for (auto& x : input) x = __float2bfloat16_rn(value(random));
    Buffer<std::uint8_t> dc(codes.size()), dh(high.size());
    Buffer<__half> ds(scales.size());
    Buffer<__nv_bfloat16> dx(input.size()), before(Rows * Tokens), after(Rows * Tokens);
    check(cudaMemcpy(dc.data, codes.data(), codes.size(), cudaMemcpyHostToDevice));
    check(cudaMemcpy(dh.data, high.data(), high.size(), cudaMemcpyHostToDevice));
    check(cudaMemcpy(ds.data, scales.data(), scales.size() * 2, cudaMemcpyHostToDevice));
    check(cudaMemcpy(dx.data, input.data(), input.size() * 2, cudaMemcpyHostToDevice));
    auto* scale_bytes = reinterpret_cast<const std::uint8_t*>(ds.data);
    if constexpr (Q5) {
        shipped::q5_small_t_mma_launch<K, Tokens>(dx.data, dc.data, dh.data, scale_bytes, Rows,
                                                Store{before.data, Rows}, nullptr);
        using Schedule = current::Q5A16SlicedKMmaSchedule<16, Tokens, 8, 2,
            ninfer::ops::Cache::cg, ninfer::ops::Cache::ca, 1, K, Tokens,
            current::Q5SlicedKReduction::Linear>;
        current::q5_a16_sliced_k_mma_kernel<Schedule, true, true><<<Rows / 16, 256>>>(
            dx.data, dc.data, dh.data, scale_bytes, Store{after.data, Rows}, Identity{}, Rows,
            K, Tokens, K, 0, current::Q5IdentityRows<16>{});
    } else {
        shipped::q4_small_t_mma_kernel<Geometry<Rows>, Tokens, Tokens><<<Rows / 16, 256>>>(
            dx.data, dc.data, scale_bytes, before.data);
        using Schedule = current::Q4A16SlicedKMmaSchedule<16, Tokens, 8, Tokens == 8 ? 2 : 1,
            ninfer::ops::Cache::cg, ninfer::ops::Cache::ca, 6, K, Tokens,
            current::Q4SlicedKReduction::Pairwise, 16>;
        current::q4_a16_sliced_k_mma_kernel<Schedule, true, true><<<Rows / 16, 256>>>(
            dx.data, dc.data, scale_bytes, Store{after.data, Rows}, Identity{}, Rows,
            K, Tokens, K, 0, current::Q4IdentityRows<16>{});
    }
    check(cudaGetLastError());
    check(cudaDeviceSynchronize());
    std::vector<std::uint16_t> expected(Rows * Tokens), actual(Rows * Tokens);
    check(cudaMemcpy(expected.data(), before.data, expected.size() * 2, cudaMemcpyDeviceToHost));
    check(cudaMemcpy(actual.data(), after.data, actual.size() * 2, cudaMemcpyDeviceToHost));
    std::size_t mismatches = 0;
    for (std::size_t i = 0; i < actual.size(); ++i) mismatches += actual[i] != expected[i];
    total_values += actual.size();
    total_mismatches += mismatches;
    std::printf("%s{\"format\":\"%s\",\"rows\":%d,\"k\":%d,\"tokens\":%d,\"seed\":%u,\"values\":%zu,\"bit_mismatches\":%zu}",
                first ? "" : ",", Q5 ? "q5" : "q4", Rows, K, Tokens, seed, actual.size(), mismatches);
    first = false;
}
int main() {
    std::printf("{\"reference\":\"1302d639\",\"method\":\"all BF16 output bits; identical generated weights and activations\",\"cases\":[");
    for (unsigned seed : {1U, 17U, 103U, 501U}) {
        compare<false, 4096, 8>(seed); compare<false, 4096, 16>(seed);
        compare<false, 7168, 8>(seed); compare<false, 7168, 16>(seed);
        compare<true, 7168, 8>(seed); compare<true, 7168, 16>(seed);
        compare<true, 12288, 8>(seed); compare<true, 12288, 16>(seed);
    }
    std::printf("],\"total_values\":%zu,\"total_bit_mismatches\":%zu}\n", total_values, total_mismatches);
    return total_mismatches ? 1 : 0;
}
